    ctx.font = `bold 92px ${FONT}`;
    ctx.fillText('EMBERWARD', FIELD.width / 2, 250);
    ctx.fillStyle = PALETTE.text;
    ctx.font = `italic 24px ${FONT}`;
    ctx.fillText('Keep the lantern lit. Slay the Dreadlord.', FIELD.width / 2, 292);
